ch-collections-1.correct:
def merge_counts(words):
	counts = {}
	for word in words:
		key = word.casefold()
		counts[key] = counts.get(key, 0) + 1
	return counts

ch-collections-3.correct:
def rotate_left(items, k):
	if not items:
		return []
	k %= len(items)
	return items[k:] + items[:k]

ch-loops-comprehensions-2.correct:
def first_repeated(items):
	seen = set()
	for item in items:
		if item in seen:
			return item
		seen.add(item)
	return None

ch-loops-comprehensions-3.correct:
def group_by_initial(words):
	groups = {}
	for word in words:
		if word:
			groups.setdefault(word[0].lower(), []).append(word)
	return groups

ch-loops-comprehensions-4.correct:
def flatten_unique(rows):
	seen = set()
	result = []
	for row in rows:
		for value in row:
			if value not in seen:
				seen.add(value)
				result.append(value)
	return result

ch-recursion-1.correct:
def sum_nested(values):
	if isinstance(values, (list, tuple)):
		return sum(sum_nested(value) for value in values)
	return values

ch-recursion-2.correct:
def reverse_text(text):
	if len(text) <= 1:
		return text
	return reverse_text(text[1:]) + text[0]

ch-exceptions-1.correct:
def parse_ints(text):
	values = []
	for field in text.split(","):
		field = field.strip()
		if field:
			values.append(int(field))
	return values

