ch-classes-3.correct:
def add_book(books, title):
	title = title.strip()
	if not title:
		raise ValueError("title must not be blank")
	return [*books, {"title": title, "done": False}]

def complete_book(books, title):
	result = [dict(book) for book in books]
	for book in result:
		if book["title"] == title:
			book["done"] = True
			break
	return result

def reading_summary(books):
	completed = sum(book["done"] for book in books)
	return {"total": len(books), "completed": completed, "remaining": len(books) - completed}

