ch-classes-4.correct:
def analyze_text(text):
	words = [word.strip(string.punctuation).casefold() for word in text.split()]
	words = [word for word in words if word]
	counts = {}
	top_word = None
	top_count = 0
	for word in words:
		counts[word] = counts.get(word, 0) + 1
		if counts[word] > top_count:
			top_word = word
			top_count = counts[word]
	return {"words": len(words), "unique_words": len(counts), "top_word": top_word, "average_length": round(sum(map(len, words)) / len(words), 2) if words else 0.0}
